package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
	"strings"

	"github.com/shopspring/decimal"
)

type SchedRec struct {
	ScAcct  string
	ScPrin  decimal.Decimal
	ScRate  decimal.Decimal
	ScYears int64
}

var WsEofFlag string = "N"
var WsBal decimal.Decimal = decimal.NewFromInt(0)
var WsYear int64 = 0
var WsCount int64 = 0
var WsBalEd string

var schedFile *os.File
var schedReader *bufio.Reader
var schedRec SchedRec
var inputDone bool

func formatWsBalEd(v decimal.Decimal) string {
	// PIC ZZ,ZZZ,ZZ9.99  len 13
	// Ensure scale 2, handle sign (not needed, values positive)
	v = v.Truncate(2)
	if v.IsNegative() {
		v = v.Neg()
	}
	// integer part: 8 digits placeholders
	// Extract integer part
	intPart := v.Truncate(0)
	// fractional part 2 digits
	frac := v.Sub(intPart).Abs()
	// frac*100 rounded - since v already has 2 decimals, get exact
	fracInt := frac.Shift(2).Truncate(0).IntPart()
	if fracInt < 0 {
		fracInt = -fracInt
	}
	// integer digits: keep low-order 8 digits if overflow
	intStr := intPart.Abs().StringFixed(0) // no exponent
	// remove sign
	if strings.HasPrefix(intStr, "-") {
		intStr = intStr[1:]
	}
	// keep only integer digits before decimal (StringFixed(0) already integer)
	// handle overflow: keep low-order 8
	numIntPlaceholders := 8
	if len(intStr) > numIntPlaceholders {
		intStr = intStr[len(intStr)-numIntPlaceholders:]
	}
	// pad to 8
	intStr = strings.Repeat("0", numIntPlaceholders-len(intStr)) + intStr

	// digit placeholder positions in edited integer part (10 chars: 0:Z 1:Z 2:, 3:Z 4:Z 5:Z 6:, 7:Z 8:Z 9:9)
	// mapping from placeholder index 0..7 -> edited position
	placeholderPos := []int{0, 1, 3, 4, 5, 7, 8, 9}
	editedInt := make([]byte, 10)
	// init commas
	editedInt[2] = ','
	editedInt[6] = ','

	suppressed := true
	for k := 0; k < numIntPlaceholders; k++ {
		d := intStr[k]
		p := placeholderPos[k]
		isLast := k == numIntPlaceholders-1 // the 9
		if isLast {
			editedInt[p] = d
			suppressed = false
		} else {
			if suppressed {
				if d != '0' {
					suppressed = false
					editedInt[p] = d
				} else {
					editedInt[p] = ' '
				}
			} else {
				editedInt[p] = d
			}
		}
	}
	// commas become spaces if still suppressed at that point
	// suppressed flag history: comma at 2 is after 2 digits, comma at 6 after 5 digits
	// Determine if any non-zero seen before comma
	// We can recompute: if first non-zero is beyond comma, comma should be space
	// Using current logic: if editedInt before comma are all spaces, then space
	if editedInt[0] == ' ' && editedInt[1] == ' ' {
		editedInt[2] = ' '
	}
	if editedInt[0] == ' ' && editedInt[1] == ' ' && editedInt[3] == ' ' && editedInt[4] == ' ' && editedInt[5] == ' ' {
		editedInt[6] = ' '
	} else {
		// if suppressed still true after processing up to before comma, but above conditions cover
		// For general correctness, check if no digit shown before comma
		// Already handled
	}

	intEditedStr := string(editedInt)
	fracStr := fmt.Sprintf("%02d", fracInt)
	return intEditedStr + "." + fracStr
}

func formatPIC99(v int64, digits int) string {
	s := strconv.FormatInt(v, 10)
	if len(s) > digits {
		s = s[len(s)-digits:]
	}
	if len(s) < digits {
		s = strings.Repeat("0", digits-len(s)) + s
	}
	return s
}

func padRight(s string, n int) string {
	if len(s) > n {
		return s[:n]
	}
	if len(s) < n {
		return s + strings.Repeat(" ", n-len(s))
	}
	return s
}

func parseLine(line string) SchedRec {
	// pad with spaces on right to 16
	if len(line) < 16 {
		line = line + strings.Repeat(" ", 16-len(line))
	}
	if len(line) > 16 {
		line = line[:16]
	}
	acct := line[0:4]
	prinRaw := line[4:11]
	rateRaw := line[11:15]
	yearsRaw := line[15:16]

	prinDigits := strings.TrimSpace(prinRaw)
	if prinDigits == "" {
		prinDigits = "0"
	}
	prinInt, _ := strconv.ParseInt(prinDigits, 10, 64)
	prinDec := decimal.New(prinInt, -2)

	rateDigits := strings.TrimSpace(rateRaw)
	if rateDigits == "" {
		rateDigits = "0"
	}
	rateInt, _ := strconv.ParseInt(rateDigits, 10, 64)
	rateDec := decimal.New(rateInt, -2)

	yearsStr := strings.TrimSpace(yearsRaw)
	var years int64
	if yearsStr != "" {
		y, _ := strconv.ParseInt(yearsStr, 10, 64)
		years = y
	}

	return SchedRec{
		ScAcct:  acct,
		ScPrin:  prinDec,
		ScRate:  rateDec,
		ScYears: years,
	}
}

func readPara() {
	line, err := schedReader.ReadString('\n')
	if err != nil {
		// EOF or other; COBOL LINE SEQUENTIAL: AT END
		// If we got some data before EOF, process it
		if len(line) > 0 {
			// strip trailing \n \r\n
			line = strings.TrimRight(line, "\r\n")
			schedRec = parseLine(line)
			return
		}
		inputDone = true
		WsEofFlag = "Y"
		return
	}
	line = strings.TrimRight(line, "\r\n")
	schedRec = parseLine(line)
}

func processPara() {
	WsBal = schedRec.ScPrin
	// PERFORM VARYING WS-YEAR FROM 1 BY 1 UNTIL WS-YEAR > SC-YEARS
	WsYear = 1
	for !(WsYear > schedRec.ScYears) {
		// COMPUTE WS-BAL ROUNDED = WS-BAL * (1 + SC-RATE / 100)
		rateDiv100 := schedRec.ScRate.Shift(-2)
		one := decimal.NewFromInt(1)
		factor := one.Add(rateDiv100)
		computed := WsBal.Mul(factor)
		WsBal = computed.Round(2)
		WsBalEd = formatWsBalEd(WsBal)
		// DISPLAY SC-ACCT " Y" WS-YEAR " " WS-BAL-ED
		fmt.Printf("%s Y%s %s\n", padRight(schedRec.ScAcct, 4), formatPIC99(WsYear, 2), WsBalEd)
		WsYear++
	}
	WsBalEd = formatWsBalEd(WsBal)
	fmt.Printf("%s FINAL %s\n", padRight(schedRec.ScAcct, 4), WsBalEd)
	WsCount++
	readPara()
}

func mainPara() {
	var err error
	schedFile, err = os.Open("input.dat")
	if err != nil {
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}
	defer schedFile.Close()
	schedReader = bufio.NewReader(schedFile)
	readPara()
	for !inputDone {
		processPara()
	}
	schedFile.Close()
	fmt.Printf("SCHEDULES: %s\n", formatPIC99(WsCount, 2))
}

func main() {
	mainPara()
}
